data.transform:
// Extract asset from GraphQL response
const asset = $.asset?.edges?.[0]?.node;

if (!asset) {
  return {
    error: true,
    message: "Asset not found"
  };
}

// Count data points
const dataPointCount = asset.dataPoints?.edges?.length || 0;

// Prepare form data
return {
  // Original asset data (for reference and mutation)
  originalAsset: asset,
  
  // Form default values
  formData: {
    code: asset.code + "-COPY",
    name: asset.name,
    type: asset.type,
    subType: asset.subType,
    manufacturer: asset.manufacturer,
    model: asset.model,
    serialNumber: asset.serialNumber,
    connectionString: asset.connectionString,
    criticality: asset.criticality,
    responsibleTeam: asset.responsibleTeam,
    status: asset.status,
    installedAt: asset.installedAt,
    lastPmAt: asset.lastPmAt,
    nextPmAt: asset.nextPmAt,
    workcenterId: asset.workcenterId,
    workcenter: asset.workcenter,
    lineId: asset.lineId,
    line: asset.line,
    cellId: asset.cellId,
    cell: asset.cell,
    deviceDriverId: asset.deviceDriverId,
    deviceDriver: asset.deviceDriver,
    copyDataPoints: true  // Default to copying data points
  },
  
  // Summary info for display
  summary: {
    originalCode: asset.code,
    dataPointCount: dataPointCount
  }
};

data.mutation:
mutation CreateAsset($payload: [AssetCreatePayloadInput!]!) {
  createAsset(payload: $payload) {
    id
    code
    name
  }
}

mutation CreateDataPoints($payload: [DataPointCreatePayloadInput!]!) {
  createDataPoint(payload: $payload) {
    id
    code
    name
  }
}

data.transform:
// Get the newly created asset
const newAsset = $.createAsset[0];
const newAssetId = newAsset.id;
const newAssetCode = newAsset.code;

// Get original asset data points from flow context
const originalAsset = $state.context.originalAsset;
const originalAssetCode = originalAsset.code;
const dataPoints = originalAsset.dataPoints?.edges || [];

// Build the payload array for batch creation
const dataPointsPayload = dataPoints.map(edge => {
  const dp = edge.node;
  
  // Replace old asset code with new asset code in the name
  // Example: "ASSET-0001.RamPosition" becomes "ASSET-0003-COPY.RamPosition"
  let newName = dp.name;
  if (dp.name && dp.name.includes('.')) {
    const parts = dp.name.split('.');
    // Replace the first part (asset code) with new asset code
    parts[0] = newAssetCode;
    newName = parts.join('.');
  }
  
  // Also update displayName description if they reference the old asset
  let newDescription = dp.description;
  if (newDescription && newDescription.includes(originalAssetCode)) {
    newDescription = newDescription.replace(new RegExp(originalAssetCode, 'g'), newAssetCode);
  }
  
  return {
    create: {
      assetId: newAssetId,
      // code: REMOVED - let Fuuz generate sequence number
      name: newName,
      displayName: dp.displayName,
      description: newDescription,
      category: dp.category,
      dataType: dp.dataType,
      unitId: dp.unitId,
      setPoint: dp.setPoint,
      upperLimit: dp.upperLimit,
      lowerLimit: dp.lowerLimit,
      upperWarning: dp.upperWarning,
      lowerWarning: dp.lowerWarning,
      tolerance: dp.tolerance,
      frequency: dp.frequency,
      isOnChange: dp.isOnChange,
      deadband: dp.deadband,
      precision: dp.precision,
      scaleFactor: dp.scaleFactor,
      historize: dp.historize,
      enabled: dp.enabled,
      alarmEnabled: dp.alarmEnabled,
      alarmPriority: dp.alarmPriority,
      isCritical: dp.isCritical
    }
  };
});

return {
  dataPointsPayload: dataPointsPayload,
  newAsset: newAsset,
  dataPointCount: dataPointsPayload.length
};

